"""Controlled WP11 survivor-fault campaign (temporary, not repository code)."""

from __future__ import annotations

from types import SimpleNamespace

import pytest


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_call(item):
    """Inject one behavior fault at each selected surviving authority seam."""
    nodeid = item.nodeid
    mp = pytest.MonkeyPatch()
    module = item.module

    if "test_health_counts_terms_by_status" in nodeid:
        from specify_cli.dashboard.handlers import glossary

        mp.setattr(glossary.GlossaryHandler, "handle_glossary_health", lambda self: None)
    elif "test_template_guard_catches_lane_in_frontmatter" in nodeid:
        mp.setattr(module, "_has_lane_in_frontmatter", lambda text: [])
    elif "test_just_fetched_at_now_returns_true" in nodeid:
        mp.setattr(module.NagCache, "has_fresh_data", lambda *args, **kwargs: False)
    elif "test_command_uses_canonical_prefix[implement]" in nodeid:
        mp.setattr(module, "generate_shim_content", lambda *args, **kwargs: "BROKEN")
    elif "test_missing_architecture_dir_raises" in nodeid:
        mp.setattr(module, "load_registry", lambda *args, **kwargs: [])
    elif "test_mission_id_for_claim_resolves_identity_from_primary" in nodeid:
        mp.setattr(module, "_mission_id_for_claim", lambda *args, **kwargs: "WRONG")
    elif "test_flip_phase_writes_snapshot_authority" in nodeid:
        mp.setattr(module.rsc, "_flip_phase", lambda *args, **kwargs: None)
    elif "test_contract_c_adapter_missing_and_malformed_return_empty" in nodeid:
        mp.setattr(module, "load_meta_or_empty", lambda *args, **kwargs: {"wrong": True})
    elif "test_1918_resolve_mid8_declines_coincidental_tail" in nodeid:
        mp.setattr(module.bn, "resolve_mid8", lambda *args, **kwargs: "WRONG")
    elif "test_over_max_still_rejected" in nodeid:
        mp.setattr(module, "UpgradeHint", lambda *args, **kwargs: SimpleNamespace())
    elif "test_issue_matrix_approval_blocker_requires_resolved_verdicts" in nodeid:
        mp.setattr(module, "_issue_matrix_approval_blocker", lambda *args, **kwargs: None)
    elif "test_skill_files_have_frontmatter" in nodeid:
        original = module._run_build

        def corrupt_build(*args, **kwargs):
            bundle_dir = original(*args, **kwargs)
            first = next((bundle_dir / "skills").glob("*/SKILL.md"))
            first.write_text("fault: missing-frontmatter\n", encoding="utf-8")
            return bundle_dir

        mp.setattr(module, "_run_build", corrupt_build)

    try:
        yield
    finally:
        mp.undo()
